"""Lumped pack thermal model for battery temperature evolution.

Pure mathematical functions modeling internal Joule heating and convective
heat dissipation to ambient air.
"""

from __future__ import annotations
import math
from typing import Dict
from ebms_sim.config import ThermalParams


def joule_heat_generation_w(current_a: float, internal_resistance_ohm: float) -> float:
    """Calculate instantaneous Joule heat generated by battery pack.

    Q_gen = I^2 * R

    Args:
        current_a: Instantaneous current [A] (positive discharge, negative charge).
        internal_resistance_ohm: Internal resistance of pack [Ohm].

    Returns:
        Heat generation rate in Watts [W].
    """
    return (current_a * current_a) * internal_resistance_ohm


def effective_thermal_resistance(
    r_th_base_k_per_w: float,
    v_ms: float = 0.0,
    cooling_factor: float = 0.02,
) -> float:
    """Calculate effective thermal resistance accounting for vehicle forward airflow.

    1 / R_th_eff = (1 / R_th_base) * (1 + cooling_factor * v_ms)

    Args:
        r_th_base_k_per_w: Static lumped thermal resistance [K/W].
        v_ms: Vehicle forward speed [m/s].
        cooling_factor: Convective heat transfer enhancement per m/s of airflow [s/m].

    Returns:
        Effective thermal resistance in K/W.
    """
    enhancement = 1.0 + max(0.0, cooling_factor * v_ms)
    return r_th_base_k_per_w / enhancement


def heat_loss_to_ambient_w(
    t_pack_c: float,
    t_ambient_c: float,
    r_th_eff_k_per_w: float,
) -> float:
    """Calculate heat transfer rate to ambient atmosphere.

    Q_loss = (T_pack - T_ambient) / R_th_eff

    Args:
        t_pack_c: Pack temperature [deg C].
        t_ambient_c: Ambient air temperature [deg C].
        r_th_eff_k_per_w: Effective thermal resistance [K/W].

    Returns:
        Heat loss rate in Watts [W] (positive = cooling down).
    """
    return (t_pack_c - t_ambient_c) / max(1e-4, r_th_eff_k_per_w)


def step_pack_temperature_c(
    t_pack_c: float,
    current_a: float,
    r_ohm: float,
    t_ambient_c: float,
    c_th_j_per_k: float,
    r_th_k_per_w: float,
    dt_s: float,
    v_ms: float = 0.0,
    cooling_factor: float = 0.02,
) -> float:
    """Analytically step battery pack temperature over time step dt.

    Uses exact solution of first-order linear ODE:
    C_th * dT/dt = Q_gen - (T - T_amb) / R_th_eff

    Args:
        t_pack_c: Initial pack temperature [deg C].
        current_a: Current during time step [A].
        r_ohm: Pack internal resistance [Ohm].
        t_ambient_c: Ambient temperature [deg C].
        c_th_j_per_k: Lumped thermal capacitance [J/K].
        r_th_k_per_w: Base thermal resistance [K/W].
        dt_s: Time step in seconds [s].
        v_ms: Vehicle speed in m/s [m/s].
        cooling_factor: Airflow convective coefficient [s/m].

    Returns:
        Updated pack temperature [deg C].
    """
    q_gen = joule_heat_generation_w(current_a, r_ohm)
    r_eff = effective_thermal_resistance(r_th_k_per_w, v_ms, cooling_factor)

    # Equilibrium temperature: T_eq = T_ambient + Q_gen * R_eff
    t_eq = t_ambient_c + (q_gen * r_eff)
    tau = max(1.0, c_th_j_per_k * r_eff)

    # Exact exponential step: T(t + dt) = T_eq + (T(t) - T_eq) * exp(-dt / tau)
    decay = math.exp(-dt_s / tau)
    return t_eq + (t_pack_c - t_eq) * decay


def step_pack_thermal(
    t_pack_c: float,
    current_a: float,
    r_ohm: float,
    t_ambient_c: float,
    thermal_params: ThermalParams,
    dt_s: float,
    v_ms: float = 0.0,
) -> Dict[str, float]:
    """Single-step thermal computation returning quantities dictionary.

    Args:
        t_pack_c: Current pack temperature [deg C].
        current_a: Current [A].
        r_ohm: Pack internal resistance [Ohm].
        t_ambient_c: Ambient air temperature [deg C].
        thermal_params: ThermalParams dataclass.
        dt_s: Time step [s].
        v_ms: Vehicle speed [m/s].

    Returns:
        Dict with 't_pack_c', 'q_gen_w', 'q_loss_w', and 'r_th_eff_k_per_w'.
    """
    q_gen = joule_heat_generation_w(current_a, r_ohm)
    r_eff = effective_thermal_resistance(
        thermal_params.r_th_k_per_w, v_ms, thermal_params.cooling_air_velocity_factor
    )
    q_loss = heat_loss_to_ambient_w(t_pack_c, t_ambient_c, r_eff)

    new_temp = step_pack_temperature_c(
        t_pack_c=t_pack_c,
        current_a=current_a,
        r_ohm=r_ohm,
        t_ambient_c=t_ambient_c,
        c_th_j_per_k=thermal_params.c_th_j_per_k,
        r_th_k_per_w=thermal_params.r_th_k_per_w,
        dt_s=dt_s,
        v_ms=v_ms,
        cooling_factor=thermal_params.cooling_air_velocity_factor,
    )

    return {
        "t_pack_c": new_temp,
        "q_gen_w": q_gen,
        "q_loss_w": q_loss,
        "r_th_eff_k_per_w": r_eff,
    }

